import{_ as a}from"./chunks/android-01-bouton-menu.B3eoFOvk.js";import{_ as t}from"./chunks/android-02-sur-cette-tablette.BZRb5xEv.js";import{_ as r}from"./chunks/android-01-accueil-image-et-bannieres.BHxZEgjx.js";import{_ as s,a as o}from"./chunks/android-02-aide-dans-l-app-fermer.Dswwg5UN.js";import{_ as n,o as d,c as l,a5 as i}from"./chunks/framework.CslsFoWx.js";const c="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/avant-01-caisse-tables.webp",u="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-01-caisse-tables.webp",p="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-10-telephone-plan.webp",m="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-02-tablette-de-salle.webp",b="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-04-borne-accueil.webp",g="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-05-borne-ecran-technique.webp",h="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-06-borne-ecran-technique-actions.webp",_="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-07-borne-aide-dans-l-app.webp",f="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/avant-09-telephone-qui-etes-vous.webp",v="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-09-telephone-qui-etes-vous.webp",T="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/avant-03-tablette-qui-etes-vous.webp",q="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-03-tablette-qui-etes-vous.webp",S="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-11-telephone-appairage-barre-etat.webp",A="/VendoraSystem-docs/captures/2026-11-08-android-salle-borne/apres-08-cloture-montant-rafale.webp",E=JSON.parse(`{"title":"Android : salle, borne, barre d'état, connexion et clôture (08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-android-salle-borne.md","filePath":"generated/preuves/2026-11-08-android-salle-borne.md","lastUpdated":null}`),C={name:"preuves/2026-11-08-android-salle-borne.md"};function y(P,e,V,x,w,j){return d(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="android-salle-borne-barre-d-etat-connexion-et-cloture-08-11-2026" tabindex="-1">Android : salle, borne, barre d&#39;état, connexion et clôture (08/11/2026) <a class="header-anchor" href="#android-salle-borne-barre-d-etat-connexion-et-cloture-08-11-2026" aria-label="Permalink to &quot;Android : salle, borne, barre d&#39;état, connexion et clôture (08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-android-salle-borne</code> · 0 image(s) · 0 trace(s)</p><div><p>Trois cartes Trello traitées ensemble (défauts relevés le 08/11 en faisant les captures Android, voir <code>docs/captures/2026-11-08-corrections-appairage/README.md</code>, <code>…-telephone-salle-reglages/</code>, <code>…-libelle-format-appareil/</code>, <code>…-bornes-images-accueil-bannieres/</code>, <code>…-borne-aide-acces-guide/</code>) :</p><ul><li>« P2 · Android : numéros de table coupés sur le plan de salle, pas de menu en mode « Tables » (caisse tablette) » ;</li><li>« P2 · Borne Android : accueil trop long en paysage, aide sous la barre d&#39;état, écran technique différent d&#39;iOS » ;</li><li>« P3 · Android : barre d&#39;état illisible, notifications redemandées, « C Caisse » en en-tête, ANR à la clôture ».</li></ul><p>Vraie stack : serveur de dev <code>localhost:8080</code>, commerce de démo FICTIF « Le Petit Bistrot (démo) » (<code>bistrot.demo+and1108@vendora.test</code>), émulateurs du projet (dérogation accordée pour ce lot) : tablette <code>emulator-5554</code> (AVD « Kds_Tablet », 1600 × 1000) et téléphone <code>emulator-5556</code> (AVD « Medium_Phone_API_36.1 », 1080 × 2400), app de debug <code>pos.android</code> construite depuis ce lot. Gestes par <code>help/tools/mobile/drv.py</code> (adb), annotations par <code>annotate.py</code> (scénarios <code>help/tools/mobile/scenarios/android-salle-borne-2026-11-08-tablette.json</code> et <code>…-telephone.json</code>). Captures « avant » : app de <code>main</code> (87aa456e) encore installée en début de lot, ou captures du 08/11 citées en lien.</p><h2 id="_1-plan-de-salle-et-mode-«-tables-»-de-la-caisse" tabindex="-1">1. Plan de salle et mode « Tables » de la caisse <a class="header-anchor" href="#_1-plan-de-salle-et-mode-«-tables-»-de-la-caisse" aria-label="Permalink to &quot;1. Plan de salle et mode « Tables » de la caisse&quot;">​</a></h2><p><strong>Causes.</strong> Plan : une table rectangulaire occupe 62 % de la hauteur de sa case ; sur une case de 54 dp (8 colonnes dans la colonne plan de 448 dp), la tuile faisait ~27 dp de haut et empilait icône (20 dp) + numéro en <code>title3</code> (24 dp) : le numéro était coupé (T3, T4, T7, T8), et la table ronde (carré inscrit ~42 dp) rognait le sien (T5, T6). Mode « Tables » : la caisse rendait le plan À LA PLACE de tout l&#39;écran de vente (retour anticipé dans <code>RegisterHome</code>), donc sans la barre de la caisse (pastille d&#39;état, Menu caisse) ni ses bandeaux.</p><p><strong>Correctifs.</strong> Numéro ajusté à la place réelle (<code>BasicText</code> + <code>TextAutoSize</code>, comme <code>minimumScaleFactor</code> sur iOS), icône et numéro côte à côte sur un rectangle bas. Le plan et l&#39;addition prennent la place du catalogue SOUS la barre de la caisse (<code>SaleScreen(floorContent = …)</code>) : Menu caisse, pastille d&#39;état, bandeaux ; les écrans ouverts depuis le menu (diagnostic, réceptions, inventaire…) reviennent au plan ; la douchette n&#39;ajoute rien au panier caché pendant le plan. <strong>iOS</strong> : même défaut (mode « Tables » en plein écran par-dessus la caisse, sans menu) → plan rendu sous la barre de la caisse dans <code>SaleView</code> (plus de <code>fullScreenCover</code>), capture clavier de la douchette coupée en mode Tables. Le numéro des tables était déjà ajusté sur iOS (<code>minimumScaleFactor</code>, voir <code>help/public/captures/telephone-salle/…</code>).</p><table tabindex="0"><thead><tr><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td><img src="'+c+'" alt=""> Caisse tablette, mode « Tables » : pas de barre de caisse (1), numéros T3, T4, T7, T8 coupés, T5 / T6 rognés (2).</td><td><img src="'+u+'" alt=""> <strong>Menu caisse</strong> (1), pastille d&#39;état (2), numéros entiers (3). Menu ouvert depuis le plan : « Clôturer la session », « Diagnostic matériel » (retour au plan vérifié).</td></tr><tr><td><img src="'+a+'" alt=""> Téléphone de salle (capture du 08/11) : T3, T4, T7, T8 coupés.</td><td><img src="'+p+'" alt=""> Numéros lisibles (1).</td></tr><tr><td><img src="'+t+'" alt=""> Tablette de salle (capture du 08/11).</td><td><img src="'+m+'" alt=""> Bandeau « Encaissement à la table » (1), numéros entiers (2).</td></tr></tbody></table><h2 id="_2-borne" tabindex="-1">2. Borne <a class="header-anchor" href="#_2-borne" aria-label="Permalink to &quot;2. Borne&quot;">​</a></h2><p><strong>Correctifs.</strong> Accueil : pied FIXE (rappel de verrouillage à gauche, langues à droite, comme l&#39;iPad), espacements resserrés sous 800 dp de haut, flèche « suite » si le contenu déborde malgré tout (police agrandie). Aide dans l&#39;app : encarts système appliqués à la vue plein écran (<code>windowInsetsPadding</code>). Écran technique aligné sur l&#39;iOS (<code>EcranTechniqueBorne</code>) : titre « Écran technique » et <strong>Retour à la borne</strong> en haut (au lieu de « Commandez ici » en bas), badge d&#39;environnement, état (dernier pull, borne, imprimante, verrouillage), <strong>Terminal de paiement</strong> (« Aucun (paiement au comptoir) » sans terminal, sinon le panneau existant), session du jour, <strong>Clôturer la journée de la borne (Z)</strong> quand un terminal est utilisable (comme l&#39;iOS), actions de même taille (Aide en ligne en <code>L</code>), message de la dernière action (« À jour », « Journée clôturée : Z produit »…). Le libellé gris « Synchroniser » isolé a disparu.</p><table tabindex="0"><thead><tr><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td><img src="'+r+'" alt=""> Langue et rappel d&#39;épinglage sous le pli.</td><td><img src="'+b+'" alt=""> Rappel (1) et langues (2) visibles sans défiler.</td></tr><tr><td><img src="'+s+'" alt=""> « Commandez ici », « Synchroniser » isolé, aide plus petite.</td><td><img src="'+g+'" alt=""> <strong>Retour à la borne</strong> (1), état (2), terminal (3).</td></tr><tr><td></td><td><img src="'+h+'" alt=""> Actions de même taille (1), message de la dernière action (2).</td></tr><tr><td><img src="'+o+'" alt=""> En-tête de l&#39;aide sous la barre d&#39;état.</td><td><img src="'+_+'" alt=""> Barre d&#39;état lisible (1), <strong>Fermer l&#39;aide</strong> dessous (2).</td></tr></tbody></table><p>Terminal de démo : la borne du commerce n&#39;a pas de terminal configuré, la clôture de la journée n&#39;apparaît donc pas à l&#39;écran (même règle que l&#39;iOS) ; elle est couverte par le test <code>ecran technique - cloturer la journee de la borne…</code>.</p><h2 id="_3-barre-d-etat-notifications-«-c-caisse-»-cloture" tabindex="-1">3. Barre d&#39;état, notifications, « C Caisse », clôture <a class="header-anchor" href="#_3-barre-d-etat-notifications-«-c-caisse-»-cloture" aria-label="Permalink to &quot;3. Barre d&#39;état, notifications, « C Caisse », clôture&quot;">​</a></h2><ul><li><strong>Barre d&#39;état</strong> : thème de fenêtre <code>Material.Light</code> + bord à bord imposé (cible 36) → icônes blanches sur fond clair. <code>SystemBarsAppearance</code> règle les icônes selon le fond (activité et dialogue d&#39;aide) ; l&#39;écran cuisine garde les siennes.</li><li><strong>Notifications</strong> : la demande (plats prêts, alertes des responsables) n&#39;est posée qu&#39;<strong>une fois par installation</strong> (<code>NotificationPermissionPolicy</code>) ; refusée, elle s&#39;active ensuite dans les réglages Android de l&#39;app (comme l&#39;iOS, où le système ne la pose qu&#39;une fois). Centre d&#39;aide <code>telephone-salle/plats-prets</code> (FR / EN / AR) complété.</li><li><strong>« C Caisse »</strong> : sans thème publié, l&#39;en-tête de « Qui êtes-vous ? » affichait le nom par défaut. Il affiche maintenant le nom du magasin, sinon le <strong>nom de l&#39;appareil</strong> reçu à l&#39;appairage (gardé dans les réglages), sinon rien. iOS : pas d&#39;en-tête de marque sur cet écran, défaut absent.</li><li><strong>Clôture de session — ANR</strong> : non reproduit (rafales de 24 Retour arrière + saisies, <code>150</code> toujours exact, avant comme après). Les traces ANR du rapport de bogue (<code>/data/anr/anr_2026-11-08-20-52-21-086</code>) montrent le fil principal de l&#39;app <strong>au repos</strong> (<code>nativePollOnce</code>) et, une minute plus tard, <code>system_server</code> bloqué 16 s par le chien de garde : l&#39;émulateur était saturé (charge de l&#39;hôte &gt; 70, jusqu&#39;à 700 pendant ce lot ; d&#39;autres apps système ont fait des ANR au même moment). Correctif préventif quand même : champs « Montant compté », commentaire et fond de caisse tenus en <code>TextFieldValue</code> local et synchrone (plus la surcharge <code>String</code> qui perdait des touches sous charge), écart mémorisé.</li></ul><table tabindex="0"><thead><tr><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td><img src="'+f+'" alt=""> Barre d&#39;état blanche sur fond clair (1), « C Caisse » (2).</td><td><img src="'+v+'" alt=""> Icônes sombres (1), « Téléphone de Lucas » (2).</td></tr><tr><td><img src="'+T+'" alt=""> Tablette : même défaut.</td><td><img src="'+q+'" alt=""> « Caisse tablette (démo) » (2).</td></tr><tr><td></td><td><img src="'+S+'" alt=""> Écran d&#39;appairage : barre d&#39;état lisible (1).</td></tr><tr><td></td><td><img src="'+A+'" alt=""> Clôture après rafale : « 150 » exact (1), écart juste (2).</td></tr></tbody></table><h2 id="trouve-en-chemin-et-corrige" tabindex="-1">Trouvé en chemin et corrigé <a class="header-anchor" href="#trouve-en-chemin-et-corrige" aria-label="Permalink to &quot;Trouvé en chemin et corrigé&quot;">​</a></h2><ul><li><strong>Réappairage sans redémarrer l&#39;app</strong> (tablette de caisse réappairée en téléphone de salle) : les ViewModels de l&#39;activité, rangés par classe, étaient repris — la salle utilisait l&#39;encaissement de la caisse (« Ouvrir la session » avec fond de caisse, pas de bandeau « Encaissement à la table »). Chaque appairage a maintenant son magasin de ViewModels (<code>PairingScopedViewModels</code>, survit à la rotation, vidé au réappairage) ; test <code>PairingViewModelStoresTest</code>.</li><li>Captures du centre d&#39;aide qui montraient les défauts remplacées (mêmes noms, FR / EN / AR) : <code>borne/preparer-la-borne/02-android-accueil-image-bannieres</code>, <code>04-android-ecran-non-epingle</code> (légende mise à jour), <code>borne/mode-technique-borne/05-android-ecran-technique</code>, <code>06-android-aide-dans-l-app</code>, <code>telephone-salle/menu-du-telephone/05-android-bouton-menu</code>, <code>telephone-salle/plan-et-addition-tablette/02-android-sur-cette-tablette</code>.</li></ul><h2 id="ce-qui-manque" tabindex="-1">Ce qui manque <a class="header-anchor" href="#ce-qui-manque" aria-label="Permalink to &quot;Ce qui manque&quot;">​</a></h2><ul><li>Capture iOS du mode « Tables » sous la barre de caisse : non faite (l&#39;outil simulateur demande une autorisation que l&#39;agent ne peut pas obtenir, et la machine était saturée pour construire le pilote XCUITest). Code compilé, tests iOS verts (294 + 2).</li></ul></div>',3)])])}const L=n(C,[["render",y]]);export{E as __pageData,L as default};
